module half_adder(Carry, Sum, A, B);
  output Carry,  Sum;
  input A, B;
  wire xor_0_out, and_0_out;
  assign xor_0_out = A ^ B;
  assign Sum = xor_0_out;
  assign and_0_out = B & A;
  assign Carry = and_0_out;
endmodule

module full_adder(Sum, CarryOut, CarryIn, a, b);
  output Sum,  CarryOut;
  input CarryIn, a, b;
  wire and_0_out, or_0_out, xor_0_out, and_1_out, xor_1_out;
  assign and_0_out = a & b;
  assign or_0_out = and_0_out | and_1_out;
  assign CarryOut = or_0_out;
  assign xor_0_out = a ^ b;
  assign and_1_out = xor_0_out & CarryIn;
  assign xor_1_out = CarryIn ^ xor_0_out;
  assign Sum = xor_1_out;
endmodule


